(window.HistoryAtlas.PERSONS = window.HistoryAtlas.PERSONS || {})["leonardo-da-vinci"] = {"id":"leonardo-da-vinci","name":"列奥纳多·达·芬奇","name_alt":"Leonardo da Vinci","group":"世界","born":1452,"died":1519,"born_approx":false,"died_approx":false,"role":"意大利文艺复兴画家、工程师、博学者","polity":"","summary":"列奥纳多生于佛罗伦萨附近的芬奇镇，在韦罗基奥作坊学艺，后长期为米兰公爵卢多维科·斯福尔扎服务，绘成《最后的晚餐》。他辗转于佛罗伦萨、米兰与罗马，作《蒙娜丽莎》，并在笔记中留下大量解剖、工程与自然研究手稿。晚年应法王弗朗索瓦一世之邀定居昂布瓦斯，1519年卒于当地。","confidence":"史料确证","sources":"达·芬奇手稿笔记、瓦萨里《艺苑名人传》、安东尼奥·德贝亚提斯旅行日记；Martin Kemp《Leonardo da Vinci: The Marvellous Works of Nature and Man》、Walter Isaacson《列奥纳多·达·芬奇传》","stops":[{"year":1452,"to":1452,"x":747.4,"y":181.3,"place":"芬奇（今意大利托斯卡纳）","event":"4月15日生于芬奇镇一带，为公证人皮耶罗的非婚生子，出生由祖父记入家簿。","kind":"出生","confidence":"史料确证","source":"祖父安东尼奥家簿；Kemp"},{"year":1472,"to":1472,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利）","event":"已在韦罗基奥作坊学艺多年，本年登记加入佛罗伦萨画家行会圣路加会。","kind":"求学","confidence":"史料确证","source":"圣路加会名册；瓦萨里《艺苑名人传》"},{"year":1481,"to":1481,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利）","event":"受圣多纳托修道院委托绘制《三王来朝》，此作未完成。","kind":"其他","confidence":"史料确证","source":"修道院委托文书；Kemp"},{"year":1483,"to":1494,"x":740.8,"y":172.9,"place":"米兰（今意大利）","event":"约1482年迁往米兰投效卢多维科·斯福尔扎，1483年4月签约绘制《岩间圣母》，并设计斯福尔扎骑马像。","kind":"任职","confidence":"史料确证","source":"《岩间圣母》合同；Kemp"},{"year":1495,"to":1498,"x":740.8,"y":172.9,"place":"米兰圣玛利亚感恩修道院（今意大利）","event":"在修道院食堂墙上绘制《最后的晚餐》，约1498年完成。","kind":"其他","confidence":"史料确证","source":"马泰奥·班代洛记述；Kemp"},{"year":1500,"to":1500,"x":752.9,"y":173.4,"place":"威尼斯（今意大利）","event":"法军占领米兰后离去，经曼托瓦为伊莎贝拉·德斯特画像素描，3月抵威尼斯，就防御奥斯曼入侵提供建议，4月返佛罗伦萨。","kind":"旅行","confidence":"史料确证","source":"洛伦佐·古斯纳斯科致伊莎贝拉·德斯特信；Kemp"},{"year":1502,"to":1502,"x":750.6,"y":178.4,"place":"伊莫拉（今意大利艾米利亚-罗马涅）","event":"任切萨雷·博尔贾的军事建筑师，巡视罗马涅诸城堡，绘制精确的伊莫拉城平面图。","kind":"任职","confidence":"史料确证","source":"博尔贾通行证；温莎皇家收藏伊莫拉地图"},{"year":1503,"to":1506,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利）","event":"受佛罗伦萨共和国委托在旧宫绘制《安吉亚里之战》壁画（未完成），约此时开始绘制《蒙娜丽莎》。","kind":"其他","confidence":"史料确证","source":"阿戈斯蒂诺·韦斯普奇批注；瓦萨里《艺苑名人传》"},{"year":1508,"to":1512,"x":740.8,"y":172.9,"place":"米兰（今意大利）","event":"受法国驻米兰总督查理·德昂布瓦斯之邀再居米兰，从事绘画、水利与解剖研究。","kind":"任职","confidence":"史料确证","source":"达·芬奇手稿；Kemp"},{"year":1513,"to":1516,"x":753.8,"y":190.8,"place":"罗马梵蒂冈观景楼（今梵蒂冈）","event":"9月前往罗马，受教宗利奥十世之弟朱利亚诺·德美第奇庇护，居于观景楼，研究光学与几何。","kind":"任职","confidence":"史料确证","source":"达·芬奇手稿；Kemp"},{"year":1517,"to":1518,"x":709.2,"y":163.5,"place":"昂布瓦斯克洛吕斯庄园（今法国）","event":"应法王弗朗索瓦一世之邀定居昂布瓦斯，1517年10月接待阿拉贡枢机路易吉一行，展示画作与解剖手稿。","kind":"任职","confidence":"史料确证","source":"德贝亚提斯旅行日记"},{"year":1519,"to":1519,"x":709.2,"y":163.5,"place":"昂布瓦斯（今法国）","event":"4月立遗嘱，5月2日卒于克洛吕斯庄园，葬于昂布瓦斯圣弗洛朗坦教堂。","kind":"去世","confidence":"史料确证","source":"达·芬奇遗嘱；梅尔齐致兄弟信"}]};
